// Please enter your KQL query (Example):
// <table name>
// | where <datetime column> between (['_startTime'] .. ['_endTime']) // Time range filtering
// | where isempty(['LinuxAgentVersion']) or <column name> == ['LinuxAgentVersion'] // Single selection filtering
// | where isempty(['WindowsAgentVersion']) or <column name> == ['WindowsAgentVersion'] // Single selection filtering
// | where isempty(['clusterId']) or <column name> == ['clusterId'] // Freetext filtering
// | take 100
traces
| where timestamp > ago(7d)
| project ID = tolower(tostring(customDimensions.ID)), controller=tostring(customDimensions.Controller), agentVersion = tostring(customDimensions.Version), tag = tostring(customDimensions.tag), message
| where tag has "addon-token-adapter-win"
| where agentVersion matches regex @"^win-\d+\.\d+\.\d+$" 
| where ID has "/microsoft.containerservice/managedclusters/"
| where message contains "error"
// | extend msg=split(message, "Z:")
// | extend l=array_length(msg)
// | extend mesg=tostring(msg[l-1])
// | extend errorMessage = case(mesg contains "error modifying iptable rules", "error modifying iptable rules",
//                              mesg contains "watch channel is closed", "watch channel is closed",                             
//                              mesg)
| summarize clustercount=dcount(ID) by message, agentVersion
| project agentVersion, clustercount, message
| order by  clustercount desc, agentVersion desc 
| take 25

// Please enter your KQL query (Example):
// <table name>
// | where <datetime column> between (['_startTime'] .. ['_endTime']) // Time range filtering
