traces
| where timestamp > ago(7d)
| project ID = tolower(tostring(customDimensions.ID)), controller=tostring(customDimensions.Controller), agentVersion = tostring(customDimensions.Version), tag = tostring(customDimensions.tag), message, IsGenevaLogsIntegrationEnabled = tostring(customDimensions.IsGenevaLogsIntegrationEnabled)
| where tag has "oms.container.log.flbplugin.ama"
| where controller == "DS"
// | where agentVersion matches regex @"win-^\d+\.\d+\.\d+$" 
| where ID has "/microsoft.containerservice/managedclusters/"
| extend errorMessage = case(message contains "Lifetime validation failed. The token is expired.", "Token Expired",
                             message contains "MonAgentManager.exe - Failed to download the Mcs configuration for MA; cannot start Agent.", "MonAgentManager.exe - Failed to download the Mcs configuration for MA; cannot start Agent.",
                             message contains "Could not obtain configuration from" and message contains "after first round of tries", "Could not obtain configuration from x after first round of tries",
                             message  contains "Data collection endpoint must be used to access configuration over private link", "Data collection endpoint must be used to access configuration over private link.",
                             message contains "ErrorCode(10054):An existing connection was forcibly closed by the remote host. Message:Failed to receive bytes from MDS", "ErrorCode(10054):An existing connection was forcibly closed by the remote host. Message:Failed to receive bytes from MDS",
                             message contains "MonAgentManager.exe - Failed to get MSI token from IMDS endpoint: http://169.254.169.254", "MonAgentManager.exe - Failed to get MSI token from IMDS endpoint: http://169.254.169.254",
                             message)
| summarize clustercount=dcount(ID) by errorMessage, agentVersion, IsGenevaLogsIntegrationEnabled
| project agentVersion, clustercount, errorMessage, IsGenevaLogsIntegrationEnabled
| order by  clustercount desc, agentVersion desc 
| take 25

