customEvents
| where timestamp > ago(7d)
| where name == "ContainerInventoryHeartBeatEvent"
| project timestamp, ID = tostring(customDimensions.ID),  isMSI = iff(notempty(tostring(customDimensions.isMSI)), tostring(customDimensions.isMSI), tostring(customDimensions.aadAuthMSIMode)), OS = tostring(customDimensions.OS), AgentVersion = tostring(customDimensions.Version)
| where OS == "Windows" 
| where AgentVersion matches regex @"^\d+\.\d+\.\d+$" 
| extend Auth = iff(isMSI =~ "true" , "MSI", "Legacy")
| summarize ClusterCount = dcount(ID) by bin(timestamp, 1d), Auth, AgentVersion
| render timechart

// Please enter your KQL query (Example):
