let _region = dynamic(null);
ToggleMonitorActivity
| where PreciseTimeStamp > ago(30m)
| project PreciseTimeStamp,RPTenant,log,msg
| project PreciseTimeStamp,RPTenant,logObj=parse_json(log)
| project PreciseTimeStamp,RPTenant,
toggleOwner=tostring(logObj["toggleOwner"]),
toggleName=tostring(logObj["toggleName"]),
toggleValue=tostring(logObj["toggleValue"]),
toggleValueType=tostring(logObj["toggleValueType"]),
toggleRegion=tostring(logObj["toggleRegion"]),
toggleDeployEnv=tostring(logObj["toggleDeployEnv"]),
toggleSource=tostring(logObj["toggleSource"]),
toggleModifiedAt=tostring(logObj["toggleModifiedAt"])
// ,logObj
| where toggleSource !=""
| where toggleDeployEnv !="e2e" or toggleSource == "globalinmaster"
| where toggleValueType == "regional"
| distinct toggleName,toggleValue,toggleDeployEnv,toggleRegion,toggleOwner
| where isempty(['_region']) or toggleRegion in (['_region'])
| where toggleName contains "omsagent"
// | distinct toggleRegion

