let ciCluster = 'https://ade.applicationinsights.io/subscriptions/13d371f9-5a39-46d5-8e1b-60158c49db84/resourceGroups/ContainerInsightsAgent-Prod/providers/microsoft.insights/components/ContainerInsightsAgent-Prod';
let ciDB = 'ContainerInsightsAgent-Prod';
cluster(ciCluster).database(ciDB).customEvents
| where timestamp > ago(1h)
| where name == "ContainerLogDaemonSetHeartbeatEvent"
| extend resourceid = iff(notempty(tostring(customDimensions.ID)), tostring(customDimensions.ID), tostring(customDimensions.AKS_RESOURCE_ID))
| extend AgentVersion = iff(notempty(tostring(customDimensions.AgentVersion)), tostring(customDimensions.AgentVersion), tostring(customDimensions.Version))
| extend ClusterType = iff(tolower(resourceid) has tolower("/Microsoft.ContainerService/managedClusters"), "AKS", "nonAKS")
| where ClusterType == "AKS"
//| where not(AgentVersion has_any ("10042022-3c05dd1b", "12032022-c9f3dc30", "01182023-095c864a", "3.1."))
| where cloud_RoleInstance startswith  "omsagent"
| extend SubscriptionId = tostring(split(resourceid, '/')[2])
    | join(Product360CustomerSubscriptions
        | project CustomerName, SubscriptionId) on SubscriptionId
    | where CustomerName !contains "Cloud + AI"
    | distinct CustomerName, SubscriptionId, ClusterType, resourceid, AgentVersion
    //| sort by count_ desc

