let ClusterCountThreshold = 50;
traces
| where timestamp > ago(4h)
| project  timestamp, ID = tostring(customDimensions.ID),  agentVersion = tostring(customDimensions.Version), region = tostring(customDimensions.Region), tag = tostring(customDimensions.tag), message, Computer = tostring(customDimensions.Computer)
| where tag has "mdsd" or tag has "windowsazuremonitoragent"
| where ID has_any ("/Microsoft.Kubernetes/connectedClusters", "/Microsoft.HybridContainerService/provisionedClusters")
| where message contains "Data collection endpoint must be used to access configuration over private link."
| where agentVersion matches regex @"^\d+\.\d+\.\d+$" or agentVersion matches regex @"^win-\d+\.\d+\.\d+$"
| summarize AggregatedErrorsCount = count() by bin(timestamp, 1h), ID, region, Computer
| where AggregatedErrorsCount > 10
| summarize total_cluster_count = dcount(ID) by region
| where total_cluster_count > ClusterCountThreshold
| project region, total_cluster_count, ClusterCountThreshold

